import { z } from 'zod';
import { abbrevSchema, cladeIdSchema } from './tree.ts';
import { breedIdSchema, fciNumberSchema, qidSchema } from './breed-names.ts';

/**
 * Schema of src/lib/data/breeds.json (generated by scripts/merge-fci.ts).
 * Every fact points to an entry of the breed's `sources[]` through `sourceId`:
 * nothing is displayed unless it traces back to a source.
 */

export const sourceIdSchema = z.string().regex(/^[a-z0-9]+(-[a-z0-9]+)*$/);

/** The 8 colour families of docs/DESIGN.md §2: an editorial choice per breed, not a datum. */
export const familySchema = z.enum(['herding', 'sighthound', 'spitz', 'mastiff', 'terrier', 'hunting', 'companion', 'ancient']);

export const breedSourceSchema = z
	.strictObject({
		id: sourceIdSchema,
		/** `editorial`: a choice made by the Dogtrails authors (e.g. the families), shown as such. */
		kind: z.enum(['wikidata', 'fci', 'parker2017', 'literature', 'editorial']),
		citation: z.string().min(1),
		/** Required except for an editorial source, which points to a file of this repository. */
		url: z.url().optional(),
		/** Repository file holding an editorial choice, e.g. `docs/DESIGN.md`. */
		path: z.string().min(1).optional(),
		/** ISO date the source was fetched or read. */
		retrieved: z.iso.date()
	})
	.refine((s) => (s.kind === 'editorial' ? !!s.path : !!s.url), {
		message: 'an editorial source needs a path, any other source a url'
	});

const sourced = { sourceId: sourceIdSchema };

/** ISO 3166-1 alpha-2, or a named region when the source gives no single country (Saluki: "Middle East"). */
export const placeSchema = z.discriminatedUnion('kind', [
	z.strictObject({ kind: z.literal('country'), iso: z.string().regex(/^[A-Z]{2}$/), label: z.string().min(1), ...sourced }),
	z.strictObject({ kind: z.literal('region'), label: z.string().min(1), ...sourced })
]);

/** [longitude, latitude] of the point drawn on the map, with the source of the point itself. */
export const coordsSchema = z.strictObject({
	lonLat: z.tuple([z.number().min(-180).max(180), z.number().min(-90).max(90)]),
	...sourced
});

export const breedSchema = z.strictObject({
	id: breedIdSchema,
	names: z.strictObject({
		en: z.string().min(1),
		fr: z.string().min(1).nullable(),
		nl: z.string().min(1).nullable(),
		/** Wikidata English label when `en` comes from data/manual/display-names.json, else `null`. */
		wikidataEn: z.string().min(1).nullable(),
		/** Source of `en`: the editorial display-names table when it overrides Wikidata. */
		enSourceId: sourceIdSchema,
		...sourced
	}),
	wikidata: qidSchema,
	fci: z.union([
		z.strictObject({
			number: fciNumberSchema,
			group: z.int().min(1).max(10),
			section: z.string().min(1),
			/** Date of provisional acceptance, `null` when definitive. */
			provisional: z.iso.date().nullable(),
			...sourced
		}),
		z.strictObject({ number: z.null(), reason: z.string().min(1) })
	]),
	parker: z.strictObject({
		/** Supplement-1 entries attached to this breed; several for size varieties. */
		entries: z
			.array(
				z.strictObject({
					abbrev: abbrevSchema,
					name: z.string().min(1),
					variant: z.string().min(1).nullable(),
					/** The entry has a leaf in tree.json (the 30-breed sample). */
					inTree: z.boolean()
				})
			)
			.min(1),
		clade: z.string().min(1),
		cladeId: cladeIdSchema,
		/** Marked `*` in supplement 1: in the clade with < 50 % bootstrap. */
		cladeLowSupport: z.boolean(),
		...sourced
	}),
	family: z.strictObject({ id: familySchema, ...sourced }),
	origin: z.strictObject({ place: placeSchema, coords: coordsSchema }),
	development: z.array(z.strictObject({ place: placeSchema, period: z.string().min(1).nullable() })),
	fixedAround: z
		.strictObject({ year: z.int().min(-20000).max(2100), approximate: z.boolean(), ...sourced })
		.nullable(),
	image: z.strictObject({ commonsFile: z.string().min(1), ...sourced }).nullable(),
	sources: z.array(breedSourceSchema).min(1)
});

export const breedsFileSchema = z
	.strictObject({
		source: z.strictObject({
			description: z.string().min(1),
			inputs: z.array(z.string().min(1)).min(1),
			notes: z.array(z.string())
		}),
		generatedBy: z.string().min(1),
		generatedAt: z.iso.datetime(),
		breeds: z.array(breedSchema).min(1)
	})
	.superRefine((f, ctx) => {
		const ids = new Set<string>();
		f.breeds.forEach((b, i) => {
			if (ids.has(b.id)) ctx.addIssue({ code: 'custom', path: ['breeds', i, 'id'], message: `duplicate id ${b.id}` });
			ids.add(b.id);
			if (!b.parker.entries.some((e) => e.inTree)) ctx.addIssue({ code: 'custom', path: ['breeds', i, 'parker'], message: 'no Parker entry in the tree' });
			const known = new Set(b.sources.map((s) => s.id));
			if (known.size !== b.sources.length) ctx.addIssue({ code: 'custom', path: ['breeds', i, 'sources'], message: 'duplicate source id' });
			// every `sourceId` anywhere in the breed must name one of its sources
			(function walk(v: unknown, path: (string | number)[]) {
				if (Array.isArray(v)) v.forEach((x, j) => walk(x, [...path, j]));
				else if (v && typeof v === 'object')
					for (const [k, x] of Object.entries(v)) {
						if (/^(sourceId|[a-z]+SourceId)$/.test(k) && typeof x === 'string' && !known.has(x))
							ctx.addIssue({ code: 'custom', path: ['breeds', i, ...path, k], message: `unknown source "${x}"` });
						else if (k !== 'sources') walk(x, [...path, k]);
					}
			})(b, []);
		});
	});

export type BreedSource = z.infer<typeof breedSourceSchema>;
export type Breed = z.infer<typeof breedSchema>;
export type BreedsFile = z.infer<typeof breedsFileSchema>;
export type Family = z.infer<typeof familySchema>;
